<?php require __DIR__.'/app/bootstrap.php';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$subject=trim((string)($_POST['subject']??'General enquiry'));$message=trim((string)($_POST['message']??''));if(mb_strlen($name)<2)$errors[]='Enter your name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(mb_strlen($message)<10)$errors[]='Please add more detail to your message.';if(!$errors){$s=db()->prepare('INSERT INTO contacts(name,email,subject,message,status) VALUES(?,?,?,?,?)');$s->execute([$name,$email,substr($subject,0,150),$message,'new']);$admin=envv('ADMIN_NOTIFICATION_EMAIL');if($admin)send_store_email($admin,'Store Admin','New contact form message','<p>From: '.e($name).' ('.e($email).')</p><p>Subject: '.e($subject).'</p><p>'.nl2br(e($message)).'</p>');flash('success','Thanks for contacting us. Your message has been received.');redirect('contact.php');}}$pageTitle='Contact us';require __DIR__.'/app/header.php';?><h1 class="page-title">We’re here to help.</h1><p class="muted">Questions about sizing, delivery, or an order? Send us a message.</p><?php if($errors):?><div class="notice error"><?=e(implode(' ',$errors))?></div><?php endif;?><form method="post" class="panel" style="max-width:700px;margin-top:25px"><?=csrf_field()?><div class="form-grid"><div class="field"><label>Your name</label><input name="name" required value="<?=e((string)($_POST['name']??''))?>"></div><div class="field"><label>Email</label><input type="email" name="email" required value="<?=e((string)($_POST['email']??''))?>"></div></div><div class="field"><label>Subject</label><input name="subject" value="<?=e((string)($_POST['subject']??''))?>"></div><div class="field"><label>Message</label><textarea name="message" required><?=e((string)($_POST['message']??''))?></textarea></div><button>Send message</button></form><?php require __DIR__.'/app/footer.php';?>
